import React from 'react';

type Props = { title: string; description?: string };

export default function PlaceholderPage({ title, description }: Props) {
  return (
    <div style={{ minHeight: '100%', backgroundColor: '#1D3FA8' }}>
      <div style={{ padding: '1.75rem 2.5rem 1.5rem', backgroundColor: '#1D3FA8' }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.55)', marginBottom: 6 }}>LogiCore</div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#ffffff', margin: 0 }}>
          {title}
        </h1>
        <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.75)', margin: '6px 0 0', maxWidth: 520 }}>
          {description ?? 'This section is coming soon.'}
        </p>
      </div>
    </div>
  );
}
